const property = items[0].json;
const formatted = {
  title: property.title,
  description: property.description,
  price: property.price,
  location: property.location,
  specs: property.specs,
  images: property.images,
  features: property.features,
  listingType: property.listingType,
  agent: property.agent,
};

items.json = [{ formatted }];
return items;

const formatted = items.json[0];
const businessId = $const('INSTAGRAM_BUSINESS_ID');
const accessToken = $const('INSTAGRAM_ACCESS_TOKEN');

if (!businessId || !accessToken) {
  throw new Error('Instagram Business ID or Access Token not configured');
}

const mediaUrl = formatted.images[0];

const mediaResponse = await fetch(`https://graph.facebook.com/v18.0/${businessId}/media`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    image_url: mediaUrl,
    caption: formatted.description,
    access_token: accessToken,
  }),
});

if (!mediaResponse.ok) {
  throw new Error('Failed to upload media to Instagram');
}

const mediaData = await mediaResponse.json();

const publishResponse = await fetch(`https://graph.facebook.com/v18.0/${businessId}/media_publish`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    creation_id: mediaData.id,
    access_token: accessToken,
  }),
});

if (!publishResponse.ok) {
  throw new Error('Failed to publish Instagram post');
}

return {
  platform: 'instagram',
  success: true,
  postUrl: `https://instagram.com/p/${mediaData.id}`,
};

const result = {
  platform: 'instagram',
  success: true,
  postUrl: items.json[0].postUrl,
};
items.json = [result];
return items;

const result = items.json[0];
const webhookUrl = $const('WEBHOOK_URL');

if (webhookUrl) {
  await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ result, platform: 'instagram' }),
  });
}

return items;
